command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$branch="work/transfer-item-budget-20261006"
$baseline="4f03ea8bc499cd8e4d064431753d4f7aefac0fff"
$candidate="d4770a2a3c16698172a2e169201f7d5f79326875"
$temp=Join-Path $env:RUNNER_TEMP ("transfer-budget-"+$env:GITHUB_RUN_ID)
$worktreeAdded=$false
try {
  Set-Location -LiteralPath $repo
  & git fetch origin main $branch --no-tags --prune
  if($LASTEXITCODE -ne 0){throw "candidate fetch failed"}
  $mainSha=(& git rev-parse refs/remotes/origin/main).Trim()
  $branchSha=(& git rev-parse ("refs/remotes/origin/"+$branch)).Trim()
  if($mainSha -ne $baseline){throw "main moved before transfer-budget validation: $mainSha"}
  if($branchSha -ne $candidate){throw "candidate moved before transfer-budget validation: $branchSha"}

  & git worktree add --detach $temp $candidate
  if($LASTEXITCODE -ne 0){throw "candidate worktree creation failed"}
  $worktreeAdded=$true
  Set-Location -LiteralPath $temp
  $env:PYTHONIOENCODING="utf-8"

  & git diff --check $baseline $candidate
  if($LASTEXITCODE -ne 0){throw "git diff --check failed"}

  & python -X utf8 tools\winui\check_python_static.py tests\winui\test_transfer_budget_contract.py tests\winui\test_transfer_budget_gui.py tests\winui\m22\test_native.py tests\winui\m23\test_native.py
  if($LASTEXITCODE -ne 0){throw "transfer-budget Python static check failed"}

  & python -X utf8 -m unittest tests.winui.test_transfer_budget_contract tests.winui.test_file_operation_controller_contract
  if($LASTEXITCODE -ne 0){throw "transfer-budget source contracts failed"}

  & python -X utf8 tools\winui\run_checks.py fast --before $baseline --head $candidate
  if($LASTEXITCODE -ne 0){throw "FAST validation failed"}

  & cmd /c tests\winui\m22\build.cmd Release
  if($LASTEXITCODE -ne 0){throw "M22 native fixture build failed"}
  $env:FLY_M22_CONFIG="Release"
  & python -X utf8 -u tests\winui\m22\test_native.py
  if($LASTEXITCODE -ne 0){throw "M22 native fixture failed"}

  & cmd /c tests\winui\m23\build.cmd Release
  if($LASTEXITCODE -ne 0){throw "M23 native fixture build failed"}
  $env:FLY_M23_CONFIG="Release"
  & python -X utf8 -u tests\winui\m23\test_native.py
  if($LASTEXITCODE -ne 0){throw "M23 native fixture failed"}

  & .\build.bat Release
  if($LASTEXITCODE -ne 0){throw "Release build failed"}

  $env:FLY_MIGRATION_CONFIGURATION="Release"
  & python -X utf8 -u tests\winui\test_transfer_budget_gui.py
  if($LASTEXITCODE -ne 0){throw "64-item focused transfer GUI failed"}

  Write-Host ("TRANSFER_BUDGET_CANDIDATE="+$candidate)
  Write-Host "TRANSFER_BUDGET_STANDARD=PASS"
} finally {
  Set-Location -LiteralPath $repo
  if($worktreeAdded){
    & git worktree remove --force $temp 2>$null
    & git worktree prune
  } elseif(Test-Path -LiteralPath $temp) {
    Remove-Item -LiteralPath $temp -Recurse -Force -ErrorAction SilentlyContinue
  }
}
